begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_api;
set local search_path=extensions,pg_catalog;
select no_plan();
select ok(to_regclass('app.rubric_versions') is not null,'native rubric versions persist');
select ok(to_regclass('app.rubric_result_revisions') is not null,'native rubric released history is separate from scalar grades');
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','75000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Native rubric golden','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)values('10000000-0000-4000-8000-000000000001','75100000-0000-4000-8000-000000000001','75000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Rubric task','Explain',10,'61000000-0000-4000-8000-000000000001');
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','75200000-0000-4000-8000-000000000001','75100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','Original immutable work');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)values('10000000-0000-4000-8000-000000000001','75100000-0000-4000-8000-000000000002','75000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Existing numeric task','Explain',10,'61000000-0000-4000-8000-000000000001');
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','75200000-0000-4000-8000-000000000002','75100000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000012','Numeric source work');
create temporary table rubric_ids(rubric_id uuid,mark_id uuid,result_id uuid,evidence_id uuid);grant select,insert,update on rubric_ids to cuevo_api;
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
insert into rubric_ids(rubric_id)select internal.create_rubric('75000000-0000-4000-8000-000000000001','School explanation','school-1','[{"key":"explanation","title":"Explanation","levels":[{"key":"developing","label":"Developing","description":"Explain a step"},{"key":"secure","label":"Secure","description":"Explain connected steps"}]},{"key":"checking","title":"Checking","levels":[{"key":"not-demonstrated","label":"Not demonstrated","description":"Check not shown"},{"key":"demonstrated","label":"Demonstrated","description":"Show checking"}]}]');
select lives_ok($$select internal.configure_assessment_rubric('75100000-0000-4000-8000-000000000001',(select rubric_id from rubric_ids),1)$$,'authorized teacher pins course rubric and policy');
select lives_ok($$select internal.mark_submission('75200000-0000-4000-8000-000000000002',0,'Numeric zero unchanged',1,0,true)$$,'numeric zero still marks through unchanged source');
select throws_ok($$select internal.configure_assessment_rubric('75100000-0000-4000-8000-000000000002',(select rubric_id from rubric_ids),1)$$,'22023',null,'numeric draft freezes rubric configuration before release');
select throws_ok($$select internal.mark_submission('75200000-0000-4000-8000-000000000001',0,'Scalar',2,0,true)$$,'22023',null,'rubric assessment cannot receive an invented scalar grade');
select throws_ok($$select internal.mark_rubric_submission('75200000-0000-4000-8000-000000000001',(select rubric_id from rubric_ids),'[{"criterionKey":"explanation","levelKey":"developing"}]','Missing checking',2,0,true)$$,'22023',null,'missing criterion is rejected without a default level');
select is((select count(*)from app.rubric_marking_revisions where submission_id='75200000-0000-4000-8000-000000000001'),0::bigint,'incomplete mark leaves no immutable draft');
select throws_ok($$select internal.mark_rubric_submission('75200000-0000-4000-8000-000000000001',(select rubric_id from rubric_ids),'[{"criterionKey":"explanation","levelKey":"invented"},{"criterionKey":"checking","levelKey":"not-demonstrated"}]','Unknown level',2,0,true)$$,'22023',null,'criterion accepts only its versioned allowed levels');
update rubric_ids set mark_id=internal.mark_rubric_submission('75200000-0000-4000-8000-000000000001',rubric_id,'[{"criterionKey":"checking","levelKey":"not-demonstrated"},{"criterionKey":"explanation","levelKey":"developing"}]','Teacher feedback',2,0,true);
select throws_ok($$select internal.configure_assessment_rubric('75100000-0000-4000-8000-000000000001',(select rubric_id from rubric_ids),2)$$,'22023',null,'configuration freezes at first rubric draft');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is((select count(*)from app.rubric_marking_revisions),0::bigint,'student cannot read rubric drafts');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update rubric_ids set result_id=internal.release_rubric_marking(mark_id,1,false);
update rubric_ids set evidence_id=(select evidence_id from app.rubric_result_revisions where id=result_id);
select is(internal.release_rubric_marking((select mark_id from rubric_ids),1,false),(select result_id from rubric_ids),'duplicate native release keeps one revision');
select is((select native_result->>'type'from app.rubric_result_revisions where id=(select result_id from rubric_ids)),'rubric','native type remains rubric');
select ok((select not(native_result?'score')and not(native_result?'maxScore')and native_result->'normalized'='null'::jsonb from app.rubric_result_revisions where id=(select result_id from rubric_ids)),'native rubric has no fabricated scalar or normalization');
select is((select native_result->'criteria'->0->>'criterionKey'from app.rubric_result_revisions where id=(select result_id from rubric_ids)),'explanation','native choices retain immutable definition order');
select is((select native_result->'criteria'->0->>'levelLabel'from app.rubric_result_revisions where id=(select result_id from rubric_ids)),'Developing','native label snapshot preserved');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is((select count(*)from app.rubric_result_revisions where submission_id='75200000-0000-4000-8000-000000000001'),0::bigint,'parent has no default rubric release access');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
savepoint rubric_atomic;
update rubric_ids set mark_id=internal.mark_rubric_submission('75200000-0000-4000-8000-000000000001',rubric_id,'[{"criterionKey":"explanation","levelKey":"secure"},{"criterionKey":"checking","levelKey":"demonstrated"}]','Correction reason',2,1,true);
select internal.release_rubric_marking((select mark_id from rubric_ids),2,true);
select internal.begin_command('rubric-rollback','result.release','0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef');
select internal.append_audit('result.release','result',(select result_id from rubric_ids),'rubric-rollback','succeeded','{}');
select internal.enqueue_event('rubric.result.released','result',(select result_id from rubric_ids),2,'{}','rubric-rollback');
rollback to rubric_atomic;
select is((select count(*)from app.rubric_result_revisions where submission_id='75200000-0000-4000-8000-000000000001'),1::bigint,'rollback removes partial rubric correction result');
select is((select count(*)from app.rubric_evidence where source_object_id='75200000-0000-4000-8000-000000000001'),1::bigint,'rollback removes partial rubric correction evidence');
reset role;
select is((select count(*)from internal.idempotency_keys where key='rubric-rollback'),0::bigint,'rollback removes rubric reservation');
select is((select count(*)from internal.audit_events where request_id='rubric-rollback'),0::bigint,'rollback removes rubric audit');
select is((select count(*)from internal.outbox_events where deduplication_key='rubric-rollback'),0::bigint,'rollback removes rubric source event');
select is((select result_id from app.current_rubric_results where submission_id='75200000-0000-4000-8000-000000000001'),(select result_id from rubric_ids),'rollback preserves prior current native projection');
select throws_ok($$update app.rubric_versions set criteria='[]'where id=(select rubric_id from rubric_ids)$$,'55000',null,'rubric definition version is immutable');
select throws_ok($$update app.rubric_result_revisions set feedback='Overwrite'where id=(select result_id from rubric_ids)$$,'55000',null,'released rubric history is immutable');
select throws_ok($$update app.assessments set max_score=20 where id='75100000-0000-4000-8000-000000000001'$$,'55000',null,'used rubric assessment context is immutable');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='app'and c.relkind in('r','p')and c.relname in('rubric_versions','assessment_rubrics','rubric_marking_revisions','rubric_result_revisions','rubric_evidence','current_rubric_results')and(not c.relrowsecurity or not c.relforcerowsecurity)),'rubric tables force RLS');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_roles r on r.rolname in('anon','authenticated','service_role','cuevo_worker')where n.nspname='app'and c.relname like '%rubric%'and has_table_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE')),'rubric records remain private from Data API and worker');
select *from finish();rollback;
